import requests
from datetime import datetime, timedelta

def get_btc_price():
    url = "https://api.coindesk.com/v1/bpi/currentprice/BTC.json"
    resp = requests.get(url).json()
    return resp['bpi']['USD']['rate_float']

def make_transaction(btc_price):
    last_check = None
    while True:
        if last_check is not None and datetime.now() - last_check > timedelta(minutes=15):
            last_check = datetime.now()
            btc_price = get_btc_price()

        # Make transaction logic here

if __name__ == "__main__":
    btc_price = get_btc_price()
    make_transaction(btc_price)

