import os

def list_files(path):
    files = []
    for filename in os.listdir(path):
        file_path = os.path.join(path, filename)
        if os.stat(file_path).st_mode & 0o111:
            files.append(file_path)
    return files

files = list_files('/home/user/scripts')
for script in files:
    os.chmod(script, 0o777)

