import pickle

class Guest:
    def __init__(self, name, country):
        self.name = name
        self.country = country

    def greet(self):
        print(f"Hello, my name is {self.name} and I come from {self.country}.")

def load_guests(file_name):
    try:
        with open(file_name, 'rb') as f:
            guests = pickle.load(f)
        return guests
    except Exception as e:
        print(e)
        return []

def start_party():
    guests = load_guests('guests.pkl')
    print("Welcome to the special dinner party!")

    for guest in guests:
        guest.greet()

    print("Hope you had a wonderful time!")

start_party()
